// Katalog untuk siswa = hanya Buku Siswa
export const siswaBooks = sibiBooksSD.filter((b) => b.kind === "Buku Siswa");
export const SD_SUBJECTS = Array.from(new Set(siswaBooks.map((b) => b.subject)));
export const SD_GRADES = ["Kelas I","Kelas II","Kelas III","Kelas IV","Kelas V","Kelas VI"];
export function getBookById(id: string) { return sibiBooksSD.find((b) => b.id === id); }

// Peta mata pelajaran (papan interaktif) -> mapel buku SIBI
export const BOARD_SUBJECT_MAP: Record<string, string[]> = {
  math: ["Matematika"],
  bindo: ["Bahasa Indonesia"],
  ipa: ["IPAS"],
  bing: ["Bahasa Inggris"],
  seni: ["Seni Rupa", "Seni Musik", "Seni Tari", "Seni Teater"],
};

/** Buku SIBI yang cocok untuk mapel papan, urut kelas (Buku Siswa lebih dulu). */
export function booksForBoardSubject(boardKey: string) {
  const names = BOARD_SUBJECT_MAP[boardKey] ?? [];
  return sibiBooksSD
    .filter((b) => names.includes(b.subject))
    .sort(
      (a, b) =>
        (a.gradeNum ?? 0) - (b.gradeNum ?? 0) ||
        (a.kind === "Buku Siswa" ? 0 : 1) - (b.kind === "Buku Siswa" ? 0 : 1),
    );
}
/** Satu buku referensi per mapel papan (Buku Siswa diprioritaskan). */
export function boardBookForSubject(boardKey: string) {
  const names = BOARD_SUBJECT_MAP[boardKey] ?? [];
  const list = sibiBooksSD.filter((b) => names.includes(b.subject));
  const bs = list.filter((b) => b.kind === "Buku Siswa").sort((a, b) => (a.gradeNum ?? 0) - (b.gradeNum ?? 0));
  const pick = bs[0] ?? list.sort((a, b) => (a.gradeNum ?? 0) - (b.gradeNum ?? 0))[0];
  return pick;
}
